'use strict';
const isPublic=document.documentElement.dataset.deployment==='public';
const siteBase=document.documentElement.dataset.basePath||'/';
const siteUrl=path=>siteBase+path.replace(/^\//,'');
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>typeof v==='number'?(Math.abs(v)>9999||Math.abs(v)<.001&&v!==0?v.toExponential(3):v.toLocaleString(undefined,{maximumSignificantDigits:4})):'—';
const state={config:null,scenarios:[],runs:[],boards:[],selected:null,task:null,activeRun:null,poll:null};
async function api(path,body){
 if(isPublic){
  if(body!==undefined)throw Error('Private discovery runs in the local companion. No data can be uploaded to this website.');
  if(path==='/api/runs')return [];
  const target={'/api/config':'/data/config.json','/api/scenarios':'/data/scenarios.json','/api/leaderboards':'/data/leaderboards.json'}[path]||(/^\/data\/tasks\/[a-f0-9]{64}\.json$/.test(path)?path:null);
  if(!target)throw Error('This feature is available in your local workspace.');
  path=siteUrl(target);
 }
 const r=await fetch(path,{method:body!==undefined?'POST':'GET',headers:body!==undefined?{'Content-Type':'application/json','X-Principia-CSRF':state.config.csrf}:{},body:body!==undefined?JSON.stringify(body):undefined});
 let data;try{data=await r.json()}catch{throw Error('The workspace did not respond. Reload the page or restart your local companion.')}
 if(!r.ok)throw Error(data.error||'Request failed');return data;
}
function error(e){$('#error').textContent=e.message||String(e);$('#error').classList.remove('hidden')}
function clearError(){$('#error').classList.add('hidden')}
function tag(text){const color={complete:'green',valid:'green',running:'purple',queued:'purple',cancelling:'amber',failed:'red',invalid:'red',unsupported:'amber',cancelled:'amber',interrupted:'amber',recovery_required:'amber'}[text]||'';return `<span class="tag ${color}">${esc(text.replaceAll('_',' '))}</span>`}
const benchmarkCount=()=>state.scenarios.filter(s=>s.task.test_exposure!=='local-user-split').length;
const methodName=id=>state.config.methods.find(m=>m.method_id===id)?.name||({agent_laboratory_explicit:'Agent Laboratory · explicit state (development)',data_to_paper_explicit:'data-to-paper · explicit state (development)'}[id])||id;
function heading(eyebrow,title,text=''){return `<div class="hero"><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1>${text?`<p class="lead">${esc(text)}</p>`:''}</div>`}
async function init(){try{[state.config,state.scenarios,state.runs,state.boards]=await Promise.all([api('/api/config'),api('/api/scenarios'),api('/api/runs'),api('/api/leaderboards')]);state.selected=state.scenarios.find(s=>s.scenario_id==='P100-054')?.scenario_id||state.scenarios[0]?.scenario_id;$('#scenario-count').textContent=benchmarkCount();$('#connection').textContent=isPublic?'Public library':'Connected · local';$('#api-settings').textContent=isPublic?'Open local workspace':'API settings';$('#api-settings').onclick=()=>isPublic?companionDialog():providerDialog();if(isPublic){$('.side-note').innerHTML='<span class="dot"></span> Shared examples and rules<p>Private discovery runs on your computer. This site accepts no folders, API keys or personal results.</p>';document.querySelector('[data-nav="runs"]').classList.add('hidden')}route()}catch(e){error(e);$('#connection').textContent='Connection unavailable'}}
function route(){window.scrollTo(0,0);clearInterval(state.poll);clearError();$('#view').innerHTML='<div class="loading">Loading workspace…</div>';const [tab,id,taskId]=location.hash.slice(1).split('/').map(decodeURIComponent);const name=tab||'scenarios';if(name==='discover'&&id&&state.scenarios.some(s=>s.scenario_id===id)){state.selected=id;state.task=taskId||null;}document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===name));$('#breadcrumb').textContent='Workspace / '+({discover:'Discover',scenarios:'Scenario library',leaderboards:'Rule leaderboards',runs:'Run history',run:'Run monitor',scenario:'Scenario guide',release:'About & release'}[name]||name);if(name==='discover')isPublic?publicDiscover():discover();else if(name==='scenarios')library();else if(name==='scenario')scenarioPage(id);else if(name==='leaderboards')boards();else if(name==='runs')isPublic?publicDiscover():runs();else if(name==='run')isPublic?publicDiscover():monitor(id);else if(name==='release')release();else discover()}
function reviewNotices(items){return (items||[]).map(a=>`<div class="note" role="note"><strong>${esc(a.scenario_id)} · ${esc(a.title)}</strong><p>${esc(a.detail)}</p><p>${esc(a.consequence)}</p></div>`).join('')}
async function inspectLocal(){clearError();$('#inspect-local').disabled=true;try{const scan=await api('/api/local/inspect',{folder:$('#local-path').value});const opts=scan.files.map(f=>`<option value="${esc(f.name)}">${esc(f.name)} · ${f.rows} rows</option>`).join('');$('#import-fields').innerHTML=`<label for="local-file">Measurement file</label><select id="local-file">${opts}</select><div id="local-columns"></div>`;const columns=()=>{const f=scan.files.find(x=>x.name===$('#local-file').value);$('#local-columns').innerHTML=`<div class="pair"><div><label for="local-target">Output column</label><select id="local-target">${f.numeric_columns.map(k=>`<option ${k==='target'||k==='y'?'selected':''}>${esc(k)}</option>`).join('')}</select></div><div><label for="local-group">Independent group column</label><select id="local-group">${f.columns.map(k=>`<option ${k==='group'?'selected':''}>${esc(k)}</option>`).join('')}</select></div></div><label>Permitted numeric inputs</label><div id="local-inputs">${f.numeric_columns.map(k=>`<label class="chip"><input type="checkbox" value="${esc(k)}">${esc(k)}</label>`).join('')}</div><p class="hint">Choose subjects, devices, batches or trajectories as groups. Related measurements will stay together. New imports are exploratory and do not automatically enter the benchmark.</p><button id="import-local">Create local scenario</button>`;const restrictInputs=()=>{document.querySelectorAll('#local-inputs input').forEach(el=>{el.disabled=[$('#local-target').value,$('#local-group').value,'sample_id'].includes(el.value);if(el.disabled)el.checked=false})};$('#local-target').onchange=restrictInputs;$('#local-group').onchange=restrictInputs;restrictInputs();$('#import-local').onclick=async()=>{clearError();try{const result=await api('/api/local/import',{folder:scan.folder,file:$('#local-file').value,output:$('#local-target').value,group:$('#local-group').value,inputs:[...document.querySelectorAll('#local-inputs input:checked')].map(e=>e.value)});state.scenarios=await api('/api/scenarios');state.selected=result.scenario_id;discover()}catch(e){error(e)}}};$('#local-file').onchange=columns;columns()}catch(e){error(e)}finally{if($('#inspect-local'))$('#inspect-local').disabled=false}}
async function start(){clearError();const method=state.config.methods.find(m=>m.method_id===$('#method').value);if(method.needs_llm&&(!state.config.api_configured||requiredModels().some(m=>state.config.capabilities[m]?.state!=='verified'))){providerDialog('Add your own key and verify the selected models before starting discovery.');return;}$('#start').disabled=true;$('#start').textContent='Creating run…';try{const r=await api('/api/runs',{scenario_id:state.selected,task_id:state.task,method_id:$('#method').value,...($('#method').value==='principia_engine_explicit'?{protocol_revision:$('#protocol').value}:{}),objective:$('#objective').disabled?'':$('#objective').value,budget_cny:Number($('#budget').value),model_roles:Object.fromEntries(Object.keys(state.config.model_roles).map(k=>[k,$('#model-'+k).value]))});location.hash='run/'+r.run_id}catch(e){error(e);$('#start').disabled=false;$('#start').textContent='Start discovery ↗'}}
async function runs(){state.runs=await api('/api/runs');if(location.hash!=='#runs')return;$('#view').innerHTML=heading('Reproducible activity','Run history','Your interactive inquiries are shown first. Campaign attempts and unsuccessful outcomes remain available in the filters.')+`<div class="toolbar"><select id="run-track" aria-label="Run track"><option value="interactive">My workspace</option><option value="engineering">Method development</option><option value="campaign">Campaign attempts</option><option value="">All runs</option></select><input id="run-search" aria-label="Search runs" placeholder="Scenario, method or run ID…"></div><p class="hint" id="run-summary"></p><div class="rows-list" id="run-rows"></div>`;let limit=30;const render=()=>{const q=$('#run-search').value.toLowerCase(),track=$('#run-track').value;const list=state.runs.filter(r=>(!track||(track==='interactive'?['interactive','engineering'].includes(r.mode||'interactive'):(r.mode||'interactive')===track))&&JSON.stringify([r.scenario_id,r.method_id,r.run_id,r.protocol_revision]).toLowerCase().includes(q));$('#run-summary').textContent=`${list.length} matching attempts · showing up to ${limit}`;$('#run-rows').innerHTML=list.slice(0,limit).map(r=>`<div class="run-row"><div><button class="link" data-run="${r.run_id}">${esc(methodName(r.method_id))} · ${esc(r.scenario_id)}</button><p>${esc(r.run_id)}${['principia_engine_explicit','agent_laboratory_explicit','data_to_paper_explicit'].includes(r.method_id)?` · Protocol ${esc(r.protocol_revision||'v1')}`:''} · ${new Date(r.created_at).toLocaleString()}</p></div>${tag(r.status)}</div>`).join('')+(list.length>limit?'<button id="more-runs">Show 30 more</button>':'')||'<div class="panel empty">No matching runs. Select a scenario in Discover to start an inquiry.</div>';document.querySelectorAll('[data-run]').forEach(b=>b.onclick=()=>location.hash='run/'+b.dataset.run);if($('#more-runs'))$('#more-runs').onclick=()=>{limit+=30;render()}};$('#run-track').onchange=()=>{limit=30;render()};$('#run-search').oninput=()=>{limit=30;render()};render()}
async function monitor(id){clearInterval(state.poll);const update=async()=>{try{const [r,cfg]=await Promise.all([api('/api/runs/'+id),api('/api/config')]);if(location.hash!=='#run/'+id)return;state.config=cfg;state.activeRun=r;const active=['queued','running','cancelling'].includes(r.status);if(['principia_engine_explicit','agent_laboratory_explicit','data_to_paper_explicit'].includes(r.method_id)){renderBoundMonitor(r);if(!active)clearInterval(state.poll);return}const receipts=r.evaluation?.receipts||[];$('#view').innerHTML=heading('Live discovery workspace',methodName(r.method_id),`${r.scenario_id} · ${r.run_id}`)+`<div class="run-banner"><div class="tags">${tag(r.status)}<span class="tag">${esc(r.progress?.stage?.replaceAll('_',' ')||'Queued')}</span></div><div>${active&&r.mode!=='campaign'?'<button class="danger" id="cancel">Cancel run</button>':''} <button id="download">Download record</button></div></div>${r.reason?`<div class="note">${esc(r.reason)}</div>`:''}<div class="progress-line ${active?'running':''}"></div><div class="stats"><div class="stat"><strong>${fmt(r.accounting?.structures??r.progress?.detail?.structures)}</strong><span>Structures actually evaluated</span></div><div class="stat"><strong>${fmt(r.accounting?.fitting_attempts??r.progress?.detail?.fitting_attempts)}</strong><span>Training fits</span></div><div class="stat"><strong>${fmt(r.accounting?.model_calls??r.events.filter(e=>e.stage==='model_request').length)}</strong><span>Model calls in this run</span></div></div>${reviewNotices(r.review_advisories)}${methodEvidence(r.method_evidence,r.events)}<div class="grid"><section class="panel"><h2>${r.rules?.length?'Frozen rule portfolio':'Candidate rules'}</h2>${r.rules?.length?r.rules.map(c=>{const e=receipts.find(x=>x.rule_id===c.rule_id);return `<div class="divider"></div><div class="tags">${tag(e?.status||'frozen')}<span class="tag">Dev ${fmt(c.dev_error)}</span>${e?`<span class="tag">Test ${fmt(e.accuracy?.primary_error)}</span>`:''}</div><h3>${esc(r.rule_presentations?.[c.rule_id]?.name||c.rule_id)}</h3><button class="link" data-rule="${esc(c.rule_id)}">Inspect rule and evidence →</button>`}).join(''):`<div class="empty">${active?'The method is working through permitted train/dev data. Rules appear after submission freeze.':'This attempt produced no frozen rules. See its execution history for the cause.'}</div>`}</section><section class="panel"><h2>Execution history</h2><p class="hint">These events are emitted by the running method.</p><div class="event-list">${r.events.slice().reverse().map(e=>`<div class="event"><time>${new Date(e.at).toLocaleTimeString()}</time><strong>${esc(e.stage.replaceAll('_',' '))}</strong><small>${esc(e.detail.message||e.detail.role&&`${e.detail.role} · ${e.detail.model||''}`||e.detail.expression||e.detail.reason||'')}</small></div>`).join('')||'<p class="hint">Waiting for a worker…</p>'}</div></section></div>`;if($('#cancel'))$('#cancel').onclick=async()=>{try{await api('/api/runs/'+id+'/cancel',{});await update()}catch(e){error(e)}};$('#download').onclick=()=>download(r,id+'.json');document.querySelectorAll('[data-rule]').forEach(b=>b.onclick=()=>showRule(r.rules.find(x=>x.rule_id===b.dataset.rule),receipts.find(x=>x.rule_id===b.dataset.rule),r.review_advisories,r.rule_presentations?.[b.dataset.rule]));if(!active)clearInterval(state.poll)}catch(e){error(e);clearInterval(state.poll)}};await update();if(['queued','running','cancelling'].includes(state.activeRun?.status))state.poll=setInterval(update,2500)}
function download(obj,name){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function release(){$('#view').innerHTML=heading('Principia ASD · 1.0 research preview','Inspectable rules. Reproducible evidence.','Explore the shared collection here, and run your own investigations in a private local companion.')+`<div class="grid"><section class="panel"><h2>What you’ll receive</h2><p>Each discovery run records its rules, executable forms, diagnostics and evidence. Test assessment is available only for the corresponding reviewed task contract.</p><h2>Available in the local companion</h2><ul class="checklist"><li>${benchmarkCount()} compact benchmark packages, plus your local imports</li><li>Real local fitting and development selection</li><li>Separate submission freeze and test evaluation</li><li>Live SiliconFlow model roles and durable request receipts</li><li>Local folder import with explicit output and groups</li><li>Run history, cancellation and downloadable Rule Cards</li></ul><h2>Preparation review findings</h2>${reviewNotices(state.config.data_preparation_advisories)}<h2>Scientific work still open</h2><ul class="checklist"><li>Final source-license and scientific contract review</li><li>Source-specific split review and portable raw-data reconstruction</li><li>Explicit learned-state lineage and corrected complexity accounting</li><li>Quality-led scenario expansion in later editions; no minimum count for this release</li><li>Remaining adapter comparisons and method-conformance coverage</li><li>Independent scientific review and external reproduction</li></ul></section><section class="panel"><h2>Integration status</h2><p class="hint">An upstream method name is never treated as evidence that its algorithm ran.</p>${state.config.methods.filter(m=>!m.available).map(m=>`<p><span class="tag amber">Pending</span> ${esc(m.name)}</p>`).join('')}<div class="note">Unsupported integrations are disabled in the discovery selector. They must pass algorithm-specific verification before they can generate ranked results.</div></section></div>`}
$('#info-dialog .close').onclick=()=>$('#info-dialog').close();$('#info-dialog').onclick=e=>{if(e.target===$('#info-dialog'))$('#info-dialog').close()};
$('#rule-dialog .close').onclick=()=>$('#rule-dialog').close();$('#rule-dialog').onclick=e=>{if(e.target===$('#rule-dialog'))$('#rule-dialog').close()};window.addEventListener('unhandledrejection',e=>{error(e.reason);e.preventDefault()});window.addEventListener('hashchange',()=>{if(state.config)route()});init();

function astaEvidence(e){
 const tree=e.search_tree||[], nodes=tree.filter(n=>n.parent_id!==null), counts=e.cohort.verified_counts;
 const report=e.handoffs.find(h=>h.stage==='evidence_report')?.output;
 const beliefLabel=d=>d.votes.some(v=>typeof v==='boolean')?fmt(d.mean):'unobserved (base '+fmt(d.mean)+')';
 const missed=Object.entries(e.conformance.checks).filter(([,ok])=>!ok).map(([key])=>key.replaceAll('_',' '));
 const nodeHtml=(n,depth=0)=>{const b=n.belief_update,x=n.experiment;return `<article class="search-node tree-depth-${depth}"><div class="panel-head"><h3>${esc(n.node_id)}</h3>${tag(x.status)}</div><p class="hint">From ${esc(n.parent_id)} · ${n.visits} visits · accumulated search reward ${fmt(n.reward_sum)}</p><p class="formula">${esc(n.frozen_claim.expression||'No valid hypothesis expression')}</p><div class="pill-row"><span class="tag">Prior ${esc(beliefLabel(b.prior))}</span><span class="tag">Posterior ${esc(beliefLabel(b.posterior))}</span><span class="tag">KL ${fmt(b.kl_posterior_to_prior)}</span><span class="tag ${b.reward>0?'purple':''}">Reward ${fmt(b.reward)}</span></div><p class="hint">Development loss ${fmt(x.result?.dev_error)} · mean comparator ${fmt(x.comparator_dev_error)} · ${x.fitting_attempts} fits</p><details><summary>Beliefs and experiment evidence</summary><p class="description">${esc(n.hypothesis.hypothesis||'Hypothesis nomination failed')}</p><p class="hint">Prior votes: ${esc(JSON.stringify(b.prior.votes))}; evidence-conditioned votes: ${esc(JSON.stringify(b.posterior.votes))}. Null means abstention.</p><p class="hint">${esc(b.reward_exclusion||(!b.sufficient_nonabstained_samples?'No observed belief in one or both phases; abstention adds no evidence or reward.':'Directional belief change determines search reward; prediction error selects the final rule portfolio.'))}</p><pre class="formula">${esc(x.result?.simplicity?.expanded_expression||x.program.expression||'No executable program')}</pre>${x.failures.map(f=>failureDetails(f)).join('')}<pre class="formula">${esc(JSON.stringify({parameters:x.result?.parameters,train_error:x.result?.train_error,dev_error:x.result?.dev_error,residuals:x.result?.residuals},null,2))}</pre></details></article>${n.children.map(id=>nodeHtml(tree.find(c=>c.node_id===id),depth+1)).join('')}`};
 return `<section class="panel"><div class="panel-head"><h2>Hypothesis search tree</h2>${tag(e.conformance.status)}</div><p class="hint">${esc(e.adaptation_version)} · ${nodes.length} hypothesis nodes · ${e.handoffs.length} model handoffs</p><p class="description">${fmt(counts.training_rows)} training rows and ${fmt(counts.development_rows)} development rows. Priors receive no measurement preview or experiment outputs; posteriors receive the recorded experiment.</p><div class="note">Beliefs are uncalibrated model judgments from ${e.configuration.belief_samples_per_phase} separate samples per phase. Surprise guides search, not the leaderboard or scientific-validity claims.</div><div>${missed.length?`<p class="note">Incomplete requirements: ${esc(missed.join('; '))}. Intermediate experiments are retained; this attempt contributes no ranked rules.</p>`:''}</div><div class="search-tree">${(tree[0]?.children||[]).map(id=>nodeHtml(tree.find(n=>n.node_id===id))).join('')}</div><details><summary>Selection decisions and conformance</summary><p class="hint">Progressive widening and UCT use the recorded visit and reward counts. Failures earn no reward.</p><pre class="formula">${esc(JSON.stringify({configuration:e.configuration,selection_history:e.selection_history,conformance:e.conformance},null,2))}</pre></details><details><summary>Model interpretation · unreviewed</summary><p class="description">${esc(report?.summary||'No completed report')}</p><p class="hint">Scientific interpretation, novelty and external review remain not assessed.</p></details></section>`;
}
function failureDetails(f){const d=f.diagnostics;if(!d)return `<p class="note">${esc(f.reason)}</p>`;const requirements=d.prediction_requirements||{};const constraints=['finite values on every row',requirements.strictly_positive?'strictly positive values':null,requirements.nonnegative?'nonnegative values':null,requirements.at_most_one?'values no greater than one':null].filter(Boolean).join('; ');return `<p class="note">${esc(f.reason)}</p><details><summary>Domain failure details</summary><p class="hint">Required: ${esc(constraints)}. These diagnostics use train/dev predictions already computed; they add no fitting.</p>${['train','dev'].map(part=>{const n=d[part];return `<p class="description"><strong>${part==='train'?'Training':'Development'}:</strong> ${fmt(n.invalid_outputs)} invalid / ${fmt(n.rows)} rows; ${fmt(n.nonfinite_outputs)} nonfinite. Finite range: ${fmt(n.finite_min)} to ${fmt(n.finite_max)}.</p>`}).join('')}<p class="hint">Parameters when the program failed</p><pre class="formula">${esc(JSON.stringify(d.fitted_parameters,null,2))}</pre></details>`}
function equationEvidence(e){
 const candidates=e.candidates||[],failures=e.failures||[],handoffs=e.role_handoffs||[];
 return `<details class="panel"><summary>Equation search · ${candidates.length} fitted systems · ${failures.length} recorded failures</summary><p>${esc(e.selection)}</p><p class="hint">${esc(e.scope)}</p>${handoffs.length?`<h3>Scientific roles</h3>${handoffs.map(h=>`<details><summary>${esc(h.role)} · ${esc(h.model)}</summary><p class="hint">Model interpretation, unreviewed. Numerical fits below are executed locally.</p><pre class="formula">${esc(h.text)}</pre></details>`).join('')}`:''}<div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Development loss</th><th>Equations</th><th>Shared parameters</th><th>Origin</th></tr></thead><tbody>${candidates.map(c=>`<tr><td>${esc(c.equation_system?.name||c.rule_id)}</td><td>${fmt(c.dev_error)}</td><td>${c.equation_system?.nodes?.length||0}</td><td>${Object.keys(c.parameters||{}).length}</td><td>${esc(c.origin)}</td></tr>`).join('')}</tbody></table></div>${failures.length?`<details><summary>Rejected equations and fitting failures</summary><pre class="formula">${esc(JSON.stringify(failures,null,2))}</pre></details>`:''}<p class="hint">Selection uses development evidence only. The download retains every candidate, shared coefficient, failed check and execution receipt.</p></details>`;
}
function methodEvidence(e,events){if(!e)return '';if(['equation-search-v1','equation-search-v2'].includes(e.version))return equationEvidence(e);if(!['asta_autodiscovery','agentrxiv','agent_laboratory','data_to_paper'].includes(e.method_id))return `<details class="panel"><summary>Recorded method evidence</summary><pre class="formula">${esc(JSON.stringify(e,null,2))}</pre></details>`;if(e.method_id==='asta_autodiscovery')return astaEvidence(e);if(e.method_id==='agentrxiv')return agentrxivEvidence(e);const paper=e.method_id==='data_to_paper';const report=e.handoffs?.find(h=>h.stage==='evidence_report')?.output;const counts=e.cohort?.verified_counts;const old=events?.find(x=>x.stage==='data_validated')?.detail;const n=counts?{train_rows:counts.training_rows,dev_rows:counts.development_rows}:old;const checked=e.verified_report;const facts=e.computed_facts||{};const sourceList=ids=>ids.map(id=>{const f=facts[id];return `<div class="divider"></div><strong>${esc(id.replaceAll('_',' '))}: ${esc(String(f.value))}</strong><p class="hint">${esc(f.computation)}</p><p class="formula">Fitted program: ${esc(f.lineage.fitted_program_sha256)}<br>Train: ${esc(f.lineage.train_records_sha256)}<br>Development: ${esc(f.lineage.development_records_sha256)}</p>`}).join('');return `<section class="panel"><div class="panel-head"><h2>${paper?'Traceable analysis':'Laboratory evidence'}</h2>${tag(e.conformance.status)}</div><p class="hint">${esc(e.adaptation_version)}</p><p class="description">${e.handoffs.length} recorded handoffs · ${e.experiments.length} program checks.</p>${n?`<p class="hint">Host-verified fitting cohort: ${fmt(n.train_rows)} training rows and ${fmt(n.dev_rows)} development rows. Model prompts contain only a small example preview.</p>`:''}${paper?`${checked?.valid?checked.sections.map(x=>`<h3>${esc(x.heading)}</h3><p class="description">${esc(x.text)}</p><details><summary>Source computations</summary>${sourceList(x.computed_references)}</details>`).join(''):'<p class="note">The analysis or report did not pass every required guard. Its failed checks remain in the downloaded record.</p>'}<p class="hint">${checked?.valid?'Numeric references and cohort counts are checked.':'No verified report was produced; inspect the retained execution diagnostics.'} Scientific interpretation, significance and originality remain unreviewed.</p>`:`<details><summary>Model interpretation · unreviewed</summary><p class="description">${esc(report?.summary||'The method did not complete its evidence report.')}</p><p class="note">Model prose can contain factual errors, including confusing the prompt preview with the fitting cohort. Use the recorded computations for numerical evidence. Scientific interpretation and originality remain unassessed.</p></details>`}<details><summary>Inspect handoffs and experiments</summary><div class="event-list">${e.handoffs.map(h=>`<div class="event"><strong>${esc(h.stage.replaceAll('_',' '))}</strong><small>${esc(h.role+' · '+h.model)} · ${h.schema_valid?'recorded':'incomplete'}</small></div>`).join('')}</div>${e.experiments.map(x=>`<div class="divider"></div><h3>${esc(x.experiment_id)} · ${esc(x.status.replaceAll('_',' '))}</h3><p class="formula">${esc(x.result?.simplicity?.expanded_expression||x.program.expression||'Missing program')}</p><p class="hint">Development loss ${fmt(x.result?.dev_error)} · ${x.fitting_attempts} fits · ${x.optimizer_evaluations} optimizer evaluations</p>${x.failures.map(f=>failureDetails(f)).join('')}`).join('')}<p class="hint">Download this run record to retain the complete handoffs, program hashes and conformance checks.</p></details></section>`}

function agentrxivEvidence(e){
 const missed=Object.entries(e.conformance.checks).filter(([,ok])=>!ok).map(([key])=>key.replaceAll('_',' '));
 const followup=e.followup, report=followup.handoffs.find(h=>h.stage==='archive_evidence_report')?.output;
 const experimentHtml=x=>`<article class="search-node"><div class="panel-head"><h3>${esc(x.experiment_id)}</h3>${tag(x.status)}</div><p class="formula">${esc(x.result?.simplicity?.expanded_expression||x.program.expression||'No valid expanded program')}</p><p class="hint">Development loss ${fmt(x.result?.dev_error)} · ${x.fitting_attempts} train fits · ${x.optimizer_evaluations} optimizer evaluations</p>${x.source_lineage?`<details><summary>Verify the reused formula</summary><p>Source: ${esc(x.source_lineage.source_lab_id)} / ${esc(x.source_lineage.source_experiment_id)}</p><p class="formula">${esc(x.source_lineage.source_expression)}</p><p>Extension (${esc(x.source_lineage.combine)}):</p><p class="formula">${esc(x.source_lineage.extension_expression)}</p><p class="hint">${esc(x.source_lineage.parameter_policy)}</p><p class="formula">Report SHA-256: ${esc(x.source_lineage.source_report_sha256)}</p></details>`:''}${x.failures.map(f=>failureDetails(f)).join('')}</article>`;
 return `<section class="panel"><div class="panel-head"><h2>Shared research archive</h2>${tag(e.conformance.status)}</div><p class="hint">${esc(e.adaptation_version)} · ${e.laboratories.length} laboratories · ${e.archive.length} completed reports · ${e.retrievals.length} peer retrievals</p><p class="description">Each laboratory starts with its own scientific state. Completed reports enter this run’s private archive. A follow-up expands a retrieved formula into a new executed program.</p><div class="note">Sequential lab scheduling, shared model configuration and a fresh archive for every attempt. Reuse is recorded; scientific independence, improvement and novelty are not established.</div>${missed.length?`<p class="note">Incomplete requirements: ${esc(missed.join('; '))}. This attempt produces no ranked rules.</p>`:''}<div class="grid">${e.laboratories.map(l=>`<article><h3>${esc(l.lab_id)} · initial investigation</h3>${tag(l.evidence.conformance.status)}<p class="hint">${l.evidence.experiments.length} experiments · ${l.evidence.handoffs.length} handoffs · no peer report supplied</p><details><summary>Inspect this laboratory</summary>${methodEvidence(l.evidence,[])}</details></article>`).join('')}</div><h3>Completed reports</h3>${e.archive.map(a=>`<details><summary>${esc(a.content.lab_id)} · ${esc(a.content.cycle_id.replaceAll('-',' '))}</summary><p class="description">${esc(a.content.report.summary)}</p><p class="hint">Model interpretation · unreviewed</p><p class="formula">${esc(a.report_id)}<br>SHA-256: ${esc(a.sha256)}</p></details>`).join('')||'<p class="hint">No completed report was eligible for publication.</p>'}<h3>Peer retrieval and follow-up</h3>${e.retrievals.map(r=>`<p class="description">${esc(r.requester)} retrieved ${esc(r.source_lab_id)}’s report.</p><p class="hint">Query: ${esc(r.query)} · lexical similarity ${fmt(r.score)}. This two-lab pilot has only one eligible foreign report.</p><p class="formula">${esc(r.report_id)} · ${esc(r.report_sha256)}</p>`).join('')||'<p class="hint">No eligible peer report was retrieved. Missing work is retained as an incomplete method execution.</p>'}${followup.experiments.map(experimentHtml).join('')}<details><summary>Follow-up interpretation · unreviewed</summary><p class="description">${esc(report?.summary||'No complete follow-up report')}</p><p class="hint">All quantitative assessments remain separate from this model-written interpretation.</p></details><details><summary>Conformance requirements</summary><pre class="formula">${esc(JSON.stringify(e.conformance,null,2))}</pre></details></section>`;
}

function boundRuleDetails(c){const m=c.simplicity;return `<section class="note"><strong>Explicit learned-state profile · development only</strong><p>${fmt(m.final_stage_parameters)} final fitted coefficients + ${fmt(m.inherited_fitted_scalars)} inherited fitted coefficients + ${fmt(m.train_statistic_scalars)} training statistics = ${fmt(m.learned_scalar_count)} learned scalars. ${fmt(m.fixed_scientific_scalars)} fixed structural constants are counted separately.</p><p>All reusable kernels are expanded below. These counts do not establish statistical degrees of freedom or include upstream measurement preprocessing.</p><details><summary>Inspect bound state and source identities</summary><pre class="formula">${esc(JSON.stringify(c.program?.states,null,2))}</pre></details></section>`}
function renderBoundMonitor(r){const active=['queued','running','cancelling'].includes(r.status),result=r.bound_result;const slots=result?.selection.nominations||[];$('#view').innerHTML=heading('Method development',methodName(r.method_id),`${r.scenario_id} · Protocol ${r.protocol_revision||'v1'} · ${r.run_id}`)+`<div class="run-banner"><div class="tags">${tag(r.status)}<span class="tag amber">Development only</span>${r.fixture?'<span class="tag amber">Scripted engineering fixture · no live models</span>':''}</div><div>${active||['interrupted','recovery_required'].includes(r.status)?'<button id="bound-cancel" class="danger">Cancel run</button>':''}${r.resume_available?'<button id="bound-resume" class="primary">Resume from checkpoint</button>':''} <button id="bound-download">Download run record</button></div></div><div class="note">This development method records fitted coefficients and train-derived statistics explicitly. Rules are selected on train/dev data. Private-test assessment, scientific review and public ranking are not available for this development run.</div>${r.reason?`<p class="note">${esc(r.reason)}</p>`:''}${r.recovery_reason?`<p class="note">${esc(r.recovery_reason)}</p>`:''}<div class="progress-line ${active?'running':''}"></div><div class="stats"><div class="stat"><strong>${fmt(r.accounting?.fitting_attempts)}</strong><span>Committed training fits</span></div><div class="stat"><strong>${fmt(r.accounting?.optimizer_evaluations)}</strong><span>Committed optimizer evaluations</span></div><div class="stat"><strong>${fmt(result?.model_requests??new Set((r.events||[]).filter(e=>e.stage==='model_request').map(e=>e.detail.request_id)).size)}</strong><span>Distinct model requests</span></div></div><div class="grid"><section class="panel"><h2>${result?'Frozen nomination slots':'Developing candidate rules'}</h2>${result?`<p class="hint">${slots.length} fixed slots · ${result.host_submission.candidates.length} retained candidates · ${result.host_submission.failures.length} failed experiments. ${result.status==='complete'?'All protocol conformance checks passed.':'The method did not complete successfully; partial artifacts remain visible.'}</p>${slots.map(slot=>{const c=r.rules.find(x=>x.candidate_id===slot.candidate_id);return `<article class="search-node"><h3>Nomination ${slot.slot}</h3>${tag(slot.status)}${c?`<p class="formula">${esc(c.program.expression)}</p><p class="hint">Dev loss ${fmt(c.dev_error)} · ${fmt(c.simplicity.learned_scalar_count)} learned scalars · ${fmt(c.simplicity.weighted_operator_count)} expanded weighted operations</p><button class="link" data-bound-rule="${esc(c.candidate_id)}">Inspect rule and bound state →</button>`:'<p class="hint">No candidate occupied this slot. The denominator remains three.</p>'}</article>`}).join('')}`:`<p class="empty">${active?'The worker is using only training and development measurements. Nominations appear after they freeze.':'No terminal nomination record is available. The execution history and recovery status explain the stopping point.'}</p>`}</section><section class="panel"><h2>Execution history</h2><p class="hint">${esc(r.progress?.stage?.replaceAll('_',' ')||'Waiting for worker')}</p><div class="event-list">${(r.events||[]).slice().reverse().map(e=>`<div class="event"><time>${new Date(e.at).toLocaleTimeString()}</time><strong>${esc(e.stage.replaceAll('_',' '))}</strong><small>${esc(e.detail.reason||e.detail.role&&`${e.detail.role} · ${e.detail.model||''}`||'')}</small></div>`).join('')}</div></section></div>${boundLaboratoryEvidence(result)}${boundPaperEvidence(result)}${result&&!['data-to-paper-explicit-state-v1-dev','data-to-paper-explicit-state-v2-dev'].includes(result.policy)?`<section class="panel"><h2>Interpretation · unreviewed</h2><p class="description">${esc(result.report?.summary||'No complete model report was produced.')}</p><ul>${(result.report?.limitations||[]).map(v=>`<li>${esc(v)}</li>`).join('')}</ul><p class="hint">Novelty, causality, practical impact and independent validation remain not assessed. Download the record for all candidates, failures, source receipts and conformance checks.</p></section>`:''}`;
$('#bound-download').onclick=()=>download(r,r.run_id+'.json');document.querySelectorAll('[data-bound-rule]').forEach(b=>b.onclick=()=>showRule(r.rules.find(c=>c.candidate_id===b.dataset.boundRule),null,[],r.rule_presentations?.[b.dataset.boundRule]));
for(const [id,action] of [['bound-resume','resume'],['bound-cancel','cancel']]){if($('#'+id))$('#'+id).onclick=async()=>{$('#'+id).disabled=true;try{await api('/api/runs/'+r.run_id+'/'+action,{});await monitor(r.run_id)}catch(e){error(e);if($('#'+id))$('#'+id).disabled=false}}}
}

function boundLaboratoryEvidence(result){
 if(result?.policy!=='agent-laboratory-explicit-state-v1-dev'||!result.handoffs)return '';
 return `<section class="panel"><h2>Laboratory handoffs and experiments</h2><p class="hint">Six required role handoffs and two proposed experiments. Host code fits only on train; dev feedback informs the second proposal. Model interpretations remain unreviewed.</p><div class="grid"><div><h3>Role handoffs</h3>${result.handoffs.map(h=>`<details><summary>${esc(h.name.replaceAll('_',' '))} · ${h.schema_valid?'contract passed':'contract failed'}</summary><p class="hint">${esc(h.role)} · ${esc(h.model)}</p><pre class="formula">${esc(JSON.stringify(h.output,null,2))}</pre><p class="hint">Output SHA-256: ${esc(h.output_sha256)}</p></details>`).join('')||'<p>No completed handoffs.</p>'}</div><div><h3>Executed experiments</h3>${result.experiments.map(e=>`<article class="search-node"><h4>${esc(e.experiment_id)}</h4>${tag(e.status)}<p class="formula">${esc(e.result?.program?.expression||e.program.expression||'No valid program')}</p><p class="hint">${fmt(e.fitting_attempts)} fits · ${fmt(e.optimizer_evaluations)} optimizer evaluations · dev loss ${fmt(e.result?.dev_error)}</p>${e.failures.map(f=>failureDetails(f)).join('')}${e.rejections.length?`<pre class="formula">${esc(JSON.stringify(e.rejections,null,2))}</pre>`:''}</article>`).join('')||'<p>No experiment executed.</p>'}</div></div><details><summary>Protocol conformance</summary><pre class="formula">${esc(JSON.stringify(result.conformance,null,2))}</pre></details></section>`;
}

function boundPaperEvidence(result){
 if(!['data-to-paper-explicit-state-v1-dev','data-to-paper-explicit-state-v2-dev'].includes(result?.policy))return '';
 const facts=result.computed_facts, report=result.verified_report;
 return `<section class="panel"><h2>Guarded analysis and statistical traceability</h2><p class="hint">One planned analysis; a repair runs only after failure. Statistics and reporting happen after nomination freeze. No private-test assessment or scientific review.</p>
 <div class="grid"><div><h3>Role handoffs</h3>${result.handoffs.map(h=>`<details><summary>${esc(h.name.replaceAll('_',' '))} · response recorded</summary><p>${esc(h.role)} · ${esc(h.model)}</p><pre class="formula">${esc(JSON.stringify(h.output,null,2))}</pre></details>`).join('')||'<p>No handoff completed.</p>'}</div>
 <div><h3>Executed analyses</h3>${result.experiments.map(e=>`<article class="search-node"><h4>${esc(e.experiment_id)}</h4>${tag(e.status)}<p class="formula">${esc(e.program.expression||'No valid expression')}</p><p>${fmt(e.fitting_attempts)} fits · ${fmt(e.optimizer_evaluations)} optimizer evaluations</p>${e.failures.map(f=>failureDetails(f)).join('')}${e.rejections.length?`<pre class="formula">${esc(JSON.stringify(e.rejections,null,2))}</pre>`:''}</article>`).join('')||'<p>No analysis executed.</p>'}</div></div>
 <details><summary>Protocol conformance</summary><pre class="formula">${esc(JSON.stringify(result.conformance,null,2))}</pre></details>
 ${facts?`<h3>Computed development statistics</h3><p class="hint">Every value is bound to the complete data partitions and frozen program. Residual spread is not a confidence interval. The comparator uses the training mean.</p><table><thead><tr><th>Quantity</th><th>Executed value</th></tr></thead><tbody>${Object.entries(facts.values).map(([key,value])=>`<tr><td>${esc(key.replaceAll('_',' '))}</td><td>${typeof value==='number'?fmt(value):esc(String(value))}</td></tr>`).join('')}</tbody></table><details><summary>Inspect computation lineage and accounting</summary><pre class="formula">${esc(JSON.stringify({facts,accounting:result.statistical_accounting},null,2))}</pre></details>`:'<p class="note">No verified statistics bundle was produced.</p>'}
 <h3>Report · numeric provenance ${report?.valid?'checked':'incomplete'}</h3><p class="hint">This check validates literal numbers and evidence identities. It does not validate interpretation, citations, causality or novelty.</p>
 ${report?.valid?report.sections.map(s=>`<h4>${esc(s.heading)}</h4><p>${esc(s.text)}</p>`).join('')+`<ul>${report.limitations.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:`<p class="note">Rendered report withheld because its provenance checks are incomplete.</p><ul>${(report?.errors||[]).map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`}
 <details><summary>Retained scientific limitations · unreviewed</summary><ul>${(result.retained_limitations||[]).map(v=>`<li>${esc(v.text)} <small>${esc(v.id)}</small></li>`).join('')}</ul></details></section>`;
}

function taskFor(s){return s?.tasks.find(t=>t.task_id===state.task)||s?.tasks[0]}
function chooseTask(s){state.task=taskFor(s)?.task_id;return taskFor(s)}
function variableButtons(t, role){return t.variables.filter(v=>v.role===role).map(v=>`<button class="variable-chip" data-variable="${esc(v.key)}" data-task="${esc(t.task_id)}" title="${esc(v.description)}">${esc(v.label)} <span>${esc(v.units)}</span></button>`).join('')}
function taskFlow(t){return `<div class="task-flow"><div><h4>Inputs</h4>${variableButtons(t,'input')}</div><span class="flow-arrow" aria-hidden="true">→</span><div><h4>Output</h4>${variableButtons(t,'output')}</div></div>`}
function bindVariables(root=document){bindTaskCards(root);root.querySelectorAll('[data-variable]').forEach(b=>b.onclick=()=>{const t=state.scenarios.flatMap(s=>s.tasks).find(t=>t.task_id===b.dataset.task),v=t?.variables.find(v=>v.key===b.dataset.variable);if(!v)return;$('#info-detail').innerHTML=`<div class="eyebrow">${esc(v.role)} variable</div><h2 id="info-title">${esc(v.label)}</h2><p class="description">${esc(v.description)}</p><dl class="kv"><dt>Column</dt><dd><code>${esc(v.key)}</code></dd><dt>Units</dt><dd>${esc(v.units)}</dd><dt>Task</dt><dd>${esc(t.display_title)}</dd></dl><p class="hint">${esc(v.provenance)}</p>`;$('#info-dialog').showModal()})}
function pathBlock(s){if(isPublic)return `<div class="path-block"><span class="eyebrow">Path in the companion download</span><code>${esc(s.package_path)}</code></div>`;return `<div class="path-block"><span class="eyebrow">Local scenario folder</span><code>${esc(s.local_path)}</code><button class="small" data-copy-path="${esc(s.scenario_id)}">Copy path</button></div>`}
function bindPaths(){document.querySelectorAll('[data-copy-path]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(state.scenarios.find(s=>s.scenario_id===b.dataset.copyPath).local_path);b.textContent='Copied'}catch{b.textContent='Select the path above to copy'}})}
function scenarioDetails(s){if(!s)return '<p>No scenarios are available.</p>';return `<div class="tags"><span class="tag purple">${esc(s.scenario_id)}</span><span class="tag">${esc(s.domain)}</span></div><h2 class="scenario-title">${esc(s.title)}</h2><p class="description">${esc(s.description)}</p><dl class="kv"><dt>Independent unit</dt><dd>${esc(s.independent_unit)}</dd><dt>Data representation</dt><dd>${esc(s.representation)}</dd><dt>Partitions</dt><dd>${fmt(s.rows.train)} train · ${fmt(s.rows.dev)} dev · ${fmt(s.rows.test)} test</dd><dt>Package size</dt><dd>${s.size.expanded_public_bytes?fmt(s.size.expanded_public_bytes/1e6)+' MB · expanded public package':s.size.expanded_bytes_including_targets?fmt(s.size.expanded_bytes_including_targets/1e6)+' MB expanded':'Local import'}</dd></dl>${pathBlock(s)}<a class="text-link" href="#scenario/${esc(s.scenario_id)}">Scenario guide, tasks and provenance →</a>`}
function taskPanel(t){return `<button class="task-summary" data-task-detail="${esc(t.task_id)}" aria-haspopup="dialog"><span><span class="eyebrow">Selected task</span><strong>${esc(t.display_title)}</strong><span class="hint">${t.inputs.length} inputs → ${esc(t.variables.find(v=>v.role==='output')?.label||t.output)} · ${esc(t.metric.primary.toUpperCase())}</span></span><span class="task-open">View details ↗</span></button>`}
function discover(){const s=state.scenarios.find(s=>s.scenario_id===state.selected),t=chooseTask(s),available=state.config.methods.filter(m=>m.available);$('#view').innerHTML=heading('Discovery workspace','Discover a rule','Choose an example or import local data, define the task, then select a discovery method.')+`<div class="grid"><section class="panel"><div class="panel-head"><h2>Configure discovery</h2><span class="step">01 / SETUP</span></div><div class="tabs"><button class="active" id="tab-library">Example scenarios</button><button id="tab-local">Local folder</button></div><div id="local-box" class="hidden"><label for="local-path">Local data folder</label><div class="pair"><input id="local-path" placeholder="/path/to/measurements"><button id="inspect-local">Inspect folder</button></div><p class="hint">CSV or CSV.gz · numeric variables · 10 MB expanded · independent group column required.</p><div id="import-fields"></div></div><div id="library-box"><label for="scenario">Scenario</label><select id="scenario">${state.scenarios.map(s=>`<option value="${esc(s.scenario_id)}" ${s.scenario_id===state.selected?'selected':''}>${esc(s.title+' · '+s.scenario_id)}</option>`).join('')}</select><div class="label-row"><label for="task">Task</label><button class="link" id="add-task">＋ Add task</button></div><select id="task">${s.tasks.map(t=>`<option value="${esc(t.task_id)}" ${t.task_id===state.task?'selected':''}>${esc(t.display_title)}${t.custom?' · custom':''}</option>`).join('')}</select><div id="task-detail" class="task-box">${taskPanel(t)}</div></div><label for="method">Discovery method</label><select id="method">${available.map(m=>`<option value="${m.method_id}" ${m.method_id===(t.equation_templates?.length?'equation_search':'principia_engine')?'selected':''}>${esc(m.name)}</option>`).join('')}</select><div id="method-info" class="method-info"></div><div id="protocol-settings" class="hidden"><label for="protocol">Search protocol</label><select id="protocol">${state.config.explicit_state_protocols.map(p=>`<option value="${esc(p.id)}">${esc(p.label)}</option>`).join('')}</select><p id="protocol-info" class="hint"></p></div><label for="objective">Research objective <span class="muted">(optional)</span></label><textarea id="objective" placeholder="Describe the relationship you want to investigate."></textarea><details id="models-settings"><summary>Model roles and run budget</summary><div class="pair">${Object.entries(state.config.model_roles).map(([role,model])=>`<div><label for="model-${role}">${role[0].toUpperCase()+role.slice(1)}</label><select id="model-${role}"><option value="" ${!model?'selected':''}>Choose a model</option>${state.config.models.map(m=>`<option ${m===model?'selected':''}>${esc(m)}</option>`).join('')}</select></div>`).join('')}</div><label for="budget">Maximum API spend for this run (CNY)</label><input id="budget" type="number" min="1" max="30" step="1" value="12"><p class="hint" id="limit-hint"></p></details><button id="start" class="primary submit">Start discovery →</button><p class="hint">Local reference methods need no API. Model methods send permitted development context to the configured provider.</p></section><section class="panel scenario-overview" id="scenario-detail">${scenarioDetails(s)}</section></div>`;
const refresh=()=>{const m=state.config.methods.find(m=>m.method_id===$('#method').value),adapter=['agent_laboratory_explicit','data_to_paper_explicit'].includes(m.method_id),bound=adapter||m.method_id==='principia_engine_explicit';$('#method-info').textContent=m.mechanism+(m.method_id.startsWith('equation_')&&!taskFor(s).quantity_units?' This task has no reviewed unit contract yet; choose a scalar method.':'');$('#protocol-settings').classList.toggle('hidden',!bound||adapter);$('#protocol').disabled=!bound||adapter;$('#protocol-info').textContent=state.config.explicit_state_protocols.find(p=>p.id===$('#protocol').value)?.description||'';$('#limit-hint').textContent=m.method_id.startsWith('equation_')?'Connected-equation search: up to 16 fits, two proposal rounds for AED (plus planner, critic and reporter on multi-role tasks), 200 optimizer evaluations per fit and a fixed shared-parameter budget. Templates and model proposals are disclosed.':bound?'Development protocol: a bounded sequence of model requests and local fits, up to 40 minutes and 4 GiB. Three frozen nomination slots. No private-test ranking.':'Up to 40 minutes, 32 model calls and 1,000 local fits. Paid requests and stopping conditions are recorded.';$('#budget').max=bound?12:30;if(bound&&Number($('#budget').value)>12)$('#budget').value=12;$('#objective').disabled=bound;$('#objective').placeholder=bound?'This development protocol uses the frozen task objective.':'Describe the relationship you want to investigate. Inputs, output and evaluation remain fixed.';$('#models-settings').classList.toggle('hidden',!m.needs_llm);Object.keys(state.config.model_roles).forEach(role=>{const el=$('#model-'+role);el.parentElement.classList.toggle('hidden',!['principia_engine','principia_engine_explicit','agent_laboratory_explicit','data_to_paper_explicit','agent_laboratory','data_to_paper','asta_autodiscovery','agentrxiv','equation_agent'].includes(m.method_id)&&role!=='coder');el.disabled=m.method_id.startsWith('direct_')});if(m.method_id.startsWith('direct_'))$('#model-coder').value=state.config.model_aliases[m.method_id.split('_')[1]]};refresh();$('#method').onchange=refresh;$('#protocol').onchange=refresh;$('#scenario').onchange=()=>{state.selected=$('#scenario').value;state.task=null;discover()};$('#task').onchange=()=>{state.task=$('#task').value;$('#task-detail').innerHTML=taskPanel(taskFor(s));refresh();bindVariables()};$('#add-task').onclick=()=>addTask(s);$('#tab-local').onclick=()=>{$('#local-box').classList.remove('hidden');$('#library-box').classList.add('hidden');$('#tab-local').classList.add('active');$('#tab-library').classList.remove('active');$('#start').disabled=true};$('#tab-library').onclick=()=>{$('#local-box').classList.add('hidden');$('#library-box').classList.remove('hidden');$('#tab-library').classList.add('active');$('#tab-local').classList.remove('active');$('#start').disabled=false};$('#inspect-local').onclick=inspectLocal;$('#start').onclick=start;bindVariables();bindPaths();}
function library(){const domains=[...new Set(state.scenarios.map(s=>s.domain))].sort();$('#view').innerHTML=heading('Example collection','Scenario library',`${benchmarkCount()} scientific examples; ${state.scenarios.filter(s=>s.tasks.some(t=>t.equation_templates?.length)).length} include connected-equation tasks. Those examples appear first. Historical tasks and their complete results remain available.`)+`<div class="toolbar"><input id="search-scenarios" aria-label="Search scenarios" placeholder="Search a phenomenon, domain or scenario ID…"><select id="domain-filter" aria-label="Filter domain"><option value="">All domains</option>${domains.map(d=>`<option>${esc(d)}</option>`).join('')}</select><label class="equation-filter"><input type="checkbox" id="equation-filter"> Connected equations</label></div><p id="library-count" class="hint"></p><div class="cards" id="scenario-cards"></div>`;const render=()=>{const q=$('#search-scenarios').value.toLowerCase(),d=$('#domain-filter').value;const list=state.scenarios.filter(s=>(!$('#equation-filter').checked||s.tasks.some(t=>t.equation_templates?.length))&&(!d||s.domain===d)&&[s.title,s.description,s.domain,s.scenario_id].join(' ').toLowerCase().includes(q)).sort((a,b)=>Number(b.tasks.some(t=>t.equation_templates?.length))-Number(a.tasks.some(t=>t.equation_templates?.length)));$('#library-count').textContent=`${list.length} matching scenarios`;$('#scenario-cards').innerHTML=list.map(s=>`<article class="scenario-card"><div class="tags"><span class="tag purple">${esc(s.scenario_id)}</span><span class="tag">${esc(s.domain)}</span>${s.tasks.some(t=>t.equation_templates?.length)?'<span class="tag purple">Equation systems</span>':''}</div><h3><a href="#scenario/${esc(s.scenario_id)}">${esc(s.title)}</a></h3><p class="description">${esc(s.description)}</p><p class="hint">${s.tasks.length} ${s.tasks.length===1?'task':'tasks'} · ${fmt(s.rows.train)} training observations</p><div class="card-footer"><a href="#scenario/${esc(s.scenario_id)}">View scenario →</a><button class="small" data-select="${esc(s.scenario_id)}">Try it yourself</button></div></article>`).join('')||'<div class="empty">No scenarios match this filter.</div>';document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.select;state.task=null;tryScenario(state.selected)})};$('#search-scenarios').oninput=render;$('#domain-filter').onchange=render;$('#equation-filter').onchange=render;render()}
function addTask(s){if(isPublic){companionDialog(s.scenario_id);return;}const presets=s.tasks.filter(t=>!t.custom);$('#info-detail').innerHTML=`<div class="eyebrow">${esc(s.title)}</div><h2 id="info-title">Add a prediction task</h2><p>Choose a new input/output combination from the available training and development variables.</p><label for="task-base">Source task</label><select id="task-base">${presets.map(t=>`<option value="${esc(t.task_id)}">${esc(t.display_title)}</option>`).join('')}</select><label for="task-name">Task name</label><input id="task-name" maxlength="120" placeholder="For example: Predict failure load from notch geometry"><label for="task-output">Output to predict</label><select id="task-output"></select><fieldset class="task-inputs"><legend>Inputs available to the method</legend><div id="task-inputs"></div></fieldset><p class="note">Custom tasks retain the original train/dev partitions. They produce a separate development portfolio, with no inherited test labels or benchmark ranking. Each task has one output; add another task for a different output.</p><p class="error hidden" id="task-error" role="alert"></p><button class="primary" id="save-task">Create task</button>`;
const populate=()=>{const t=presets.find(t=>t.task_id===$('#task-base').value);$('#task-output').innerHTML=t.variables.map(v=>`<option value="${esc(v.key)}" ${v.role==='output'?'selected':''}>${esc(v.label)} (${esc(v.key)})</option>`).join('');$('#task-inputs').innerHTML=t.variables.map(v=>`<label class="variable-choice"><input type="checkbox" value="${esc(v.key)}" ${v.role==='input'?'checked':''}><span><strong>${esc(v.label)}</strong><small>${esc(v.key)} · ${esc(v.units)}</small></span></label>`).join('');const restrict=()=>document.querySelectorAll('#task-inputs input').forEach(c=>{c.disabled=c.value===$('#task-output').value;if(c.disabled)c.checked=false});$('#task-output').onchange=restrict;restrict()};populate();$('#task-base').onchange=populate;$('#save-task').onclick=async()=>{const button=$('#save-task');button.disabled=true;$('#task-error').classList.add('hidden');try{const result=await api('/api/tasks',{scenario_id:s.scenario_id,base_task_id:$('#task-base').value,title:$('#task-name').value,output:$('#task-output').value,inputs:[...document.querySelectorAll('#task-inputs input:checked')].map(e=>e.value)});state.scenarios=await api('/api/scenarios');state.selected=s.scenario_id;state.task=result.task_id;$('#info-dialog').close();if(location.hash.startsWith('#discover'))discover();else location.hash='discover'}catch(e){$('#task-error').textContent=e.message;$('#task-error').classList.remove('hidden');button.disabled=false}};$('#info-dialog').showModal()}
function math(text,display=false){if(!text)return '';try{return katex.renderToString(text,{output:'mathml',displayMode:display,throwOnError:true,trust:false,maxExpand:1000})}catch{return `<code>${esc(text)}</code>`}}
function showRule(c,e,advisories=[],presentation){const p=presentation||{},method=state.config.methods.find(m=>m.method_id===c.method_id);$('#rule-detail').innerHTML=`<div class="eyebrow">Rule card</div><h2 id="rule-title">${esc(p.name||c.rule_id||c.candidate_id)}</h2><p class="hint">${esc(methodName(c.method_id))} · ${esc(c.task_id||'Development task')}</p>${p.latex?`<div class="math-panel${p.equations?.length?' equation-math-panel':''}">${math(p.latex,true)}</div><button id="copy-latex" class="small">Copy LaTeX</button>`:`<p class="note">${esc(p.unavailable||'Mathematical rendering unavailable for this retained program.')}</p>`}${equationDetails(p)}<section class="rule-section"><h3>What this rule expresses</h3><p class="description">${esc(p.interpretation||'Inspect the executable record for this program’s complete behavior.')}</p><p class="hint">${esc(p.interpretation_scope||'Scientific interpretation remains unreviewed.')}</p></section>${p.regions?.length?`<details class="rule-section"><summary>Decision regions · all ${p.regions.length} terminal paths</summary><p class="hint">The indicator is 1 only inside its region. Every threshold and terminal prediction is listed in the parameter table.</p>${p.regions.map((r,i)=>`<div class="math-panel">${math(`R_{${i+1}}: `+r.condition,true)}<small>Returns ${math(r.symbol)}</small></div>`).join('')}</details>`:''}<section class="rule-section"><h3>Variables</h3><div class="table-wrap"><table><thead><tr><th>Symbol</th><th>Meaning</th><th>Units</th></tr></thead><tbody>${(p.variables||[]).map(v=>`<tr><td>${math(v.symbol)}</td><td>${esc(v.description)}<br><small class="muted">${esc(v.key)}</small></td><td>${esc(v.units)}</td></tr>`).join('')}</tbody></table></div></section><section class="rule-section"><h3>Test performance</h3><div class="performance-grid"><div><span>Test loss${e?.accuracy?.primary?' · '+esc(e.accuracy.primary.toUpperCase()):''}</span><strong>${fmt(e?.accuracy?.primary_error)}</strong></div><div><span>Coverage</span><strong>${e?.coverage?`${e.coverage.predicted} / ${e.coverage.eligible}`:'Not assessed'}</strong></div><div><span>Development loss</span><strong>${fmt(c.dev_error)}</strong></div></div><p class="hint">${e?.accuracy?`Accuracy gate: ${e.accuracy_gate?'passed the frozen reference comparison':'below the required comparison'}. ${esc(e.test_exposure||'Retrospective evidence')}.`:'No test receipt exists for this rule. Development loss is not a blind-test score.'}</p><dl class="kv"><dt>Rule operators</dt><dd>${fmt(e?.simplicity?.weighted_operator_count??c.simplicity?.weighted_operator_count)} weighted operations</dd><dt>Parameters</dt><dd>${fmt(e?.simplicity?.free_parameters??c.simplicity?.free_parameters)} recorded free coefficients</dd><dt>Input sensitivity</dt><dd>${fmt(e?.stability?.mean_relative_sensitivity)} · diagnostic only</dd><dt>Uncertainty</dt><dd>${esc(e?.uncertainty?.reason||'No independently justified uncertainty assessment')}</dd></dl></section><section class="rule-section"><h3>ASD recipe</h3><p><strong>${esc(methodName(c.method_id))}</strong></p><p class="description">${esc(method?.mechanism||'Refer to the recorded method configuration.')}</p><dl class="kv"><dt>Rule origin</dt><dd>${esc(c.origin||'Frozen nomination')}</dd><dt>Models</dt><dd>${esc((c.model_ids||[]).join(' · ')||'See the run record; no model identity is inferred')}</dd><dt>Method revision</dt><dd>${esc(c.method_version||c.policy||'Recorded in the run manifest')}</dd></dl><p class="hint">The method generated candidates, fitted permitted training data and selected on development evidence. The downloaded record preserves this rule’s exact executable form and provenance.</p></section><section class="rule-section"><h3>Parameter values</h3><p class="hint">Four significant digits for reading; full precision is preserved in the downloaded record.</p><div class="table-wrap"><table><thead><tr><th>Symbol</th><th>Value</th><th>Role</th></tr></thead><tbody>${(p.parameters||[]).map(v=>`<tr><td>${math(v.symbol)}</td><td class="numeric">${fmt(v.value)}</td><td>${esc(v.description)}</td></tr>`).join('')||'<tr><td colspan="3">No fitted parameters recorded.</td></tr>'}</tbody></table></div></section><section class="rule-section"><h3>Applicability and reproducibility</h3><p class="description">${esc(p.formula_scope||'Use the executable record to reproduce this rule.')}</p><p class="hint">Parameter units and physical meaning require scientific review. A fitted coefficient is not automatically a physical constant.</p><details><summary>Scientific scope and accounting limitations</summary>${reviewNotices(advisories)}${c.representation==='equation-system-v1'?'<p>Complexity expands every equation operation and counts shared fitted parameters once. Fixed reference constants and measured inputs are listed separately. Upstream source preprocessing remains part of the task provenance.</p>':c.representation==='bound_expression_v1'?boundRuleDetails(c):'<p>Historical complexity counts the submitted expression or tree relative to prepared inputs. Upstream preprocessing and some inherited learned state are not included. Complexity and Pareto labels remain provisional pending versioned correction.</p>'}<p>Novelty, causality, practical impact and external validation remain not assessed.</p></details><details><summary>Full reproducibility record</summary><pre class="formula">${esc(JSON.stringify({rule:c,evaluation:e},null,2))}</pre></details><button id="download-rule">Download Rule Card</button></section>`;if($('#copy-latex'))$('#copy-latex').onclick=async()=>{try{await navigator.clipboard.writeText(p.expanded_latex||p.latex);$('#copy-latex').textContent='LaTeX copied'}catch{error('Clipboard unavailable; download the Rule Card for the LaTeX source.')}};$('#download-rule').onclick=()=>download({rule:c,evaluation:e,presentation:p},(c.rule_id||c.candidate_id)+'.json');$('#rule-dialog').showModal();$('#rule-dialog').scrollTop=0}
async function boards(){state.boards=await api('/api/leaderboards');$('#view').innerHTML=heading('Task-specific comparisons','Rule leaderboards','Each task has its own leaderboard. Compare test performance and rule structure, then open a rule to inspect its formula and evidence.')+`<div class="toolbar"><div><label for="board-scenario">Scenario</label><select id="board-scenario" aria-label="Leaderboard scenario">${state.scenarios.map(s=>`<option value="${esc(s.scenario_id)}" ${s.scenario_id===state.selected?'selected':''}>${esc(s.title)}</option>`).join('')}</select></div><div><label for="board-task">Task</label><select id="board-task" aria-label="Leaderboard task"></select></div><button id="download-board">Download JSON</button></div><div id="board-results"></div>`;const render=async()=>{const s=state.scenarios.find(x=>x.scenario_id===$('#board-scenario').value),t=s.tasks.find(t=>t.task_id===$('#board-task').value),b=await loadBoard(s.scenario_id,t.task_id);if(!$('#board-task')||$('#board-task').value!==t.task_id)return;state.selected=s.scenario_id;state.task=t.task_id;$('#board-results').innerHTML=`<section class="panel">${taskPanel(t)}<p class="hint">${esc(t.task_id)} · ${b?.rules.length||0} rules · ${b?.attempts?.length||0} attempts</p></section>`+tableForTask(s,t,b,'data-board-rule')+`<details class="panel"><summary>How to read this leaderboard</summary><p>Loss is compared only within this task, using its declared metric and complete eligible cohort. Lower is better. Invalid and incomplete outcomes remain visible.</p><p>Operators are weighted expanded operations. Parameters are the recorded free coefficients. Historical preprocessing and inherited learned state are not fully captured, so complexity and Pareto labels are provisional. Sensitivity is diagnostic and appears on each Rule Card.</p><p>Local custom tasks show development portfolios without test ranking. Scientific review is separate from numerical results.</p>${reviewNotices(s.review_advisories)}</details>`;$('#download-board').disabled=!b;$('#download-board').onclick=()=>download(b,t.task_id+'-leaderboard.json');document.querySelectorAll('[data-board-rule]').forEach(el=>el.onclick=()=>{const r=b.rules.find(x=>x.rule_id===el.dataset.boardRule);showRule(r.card||r,r,s.review_advisories,b.rule_presentations?.[r.rule_id])});bindVariables()};const select=()=>{const s=state.scenarios.find(s=>s.scenario_id===$('#board-scenario').value);$('#board-task').innerHTML=s.tasks.map(t=>`<option value="${esc(t.task_id)}" ${t.task_id===state.task?'selected':''}>${esc(t.display_title)}</option>`).join('');render()};$('#board-scenario').onchange=select;$('#board-task').onchange=render;select()}


// Public presentation and private local execution share the same task/Rule Card views.
function tryScenario(sid,tid){state.selected=sid;state.task=tid||null;if(isPublic){companionDialog(sid,tid);return;}location.hash='discover/'+encodeURIComponent(sid)+(tid?'/'+encodeURIComponent(tid):'')}
function bindTaskCards(root=document){root.querySelectorAll('[data-task-detail]').forEach(b=>b.onclick=()=>{const t=state.scenarios.flatMap(s=>s.tasks).find(t=>t.task_id===b.dataset.taskDetail);if(!t)return;$('#task-modal-content').innerHTML=`<div class="eyebrow">Prediction task</div><h2 id="task-dialog-title">${esc(t.display_title)}</h2><p class="hint">${t.equation_templates?.length?'Connected-equation task · ':''}${t.inputs.length} inputs · ${esc(t.metric.primary.toUpperCase())} · ${esc(t.metric.aggregation||'task-defined aggregation')}</p>${t.description?`<p class="description">${esc(t.description)}</p>`:''}${taskFlow(t)}${!isPublic&&t.local_path?`<details><summary>Task data location</summary><code class="local-path">${esc(t.local_path)}</code></details>`:''}<p class="description">${esc(t.observation_window||'Training fit, development selection and separate test assessment.')}</p><p class="hint">${t.custom?'Custom question. Development results only; no inherited test ranking.':'Select any variable for its meaning, units and source lineage.'}</p>`;bindVariables($('#task-modal-content'));$('#task-dialog').showModal()})}
function ruleFamilies(b){const groups=new Map();for(const r of b.rules){const p=b.rule_presentations?.[r.rule_id]||{},key=p.structure_id||r.rule_id;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r)}return [...groups.values()]}
function tableForTask(s,t,b,attribute='data-explored-rule'){
 if(!b)return '<div class="panel empty">No explored rules are recorded for this task yet.</div>';
 const groups=ruleFamilies(b),head=`<thead><tr><th>Rule</th><th>Method</th><th>Test loss <small>${esc(t.metric.primary.toUpperCase())}</small></th><th>Rule operators</th><th>Parameters</th><th>Status</th></tr></thead>`;
 const baseName=r=>{const p=b.rule_presentations?.[r.rule_id]||{};return p.family_name||p.name||r.rule_id},totals=new Map(),ordinals=new Map(),labels=new Map();
 for(const g of groups){const n=baseName(g[0]);totals.set(n,(totals.get(n)||0)+1)}
 for(const g of groups){const n=baseName(g[0]),i=(ordinals.get(n)||0)+1;ordinals.set(n,i);for(const r of g)labels.set(r.rule_id,n+(totals.get(n)>1?' · Form '+i:''))}
 const row=(r,fit)=>{return `<tr><td><button class="link rule-name" ${attribute}="${esc(r.rule_id)}">${esc(labels.get(r.rule_id))}${fit?' · Fit '+fit:''}</button>${r.card?.representation==='equation-system-v1'?'<br><span class="tag purple">Connected equations</span>':''}</td><td>${esc(methodName(r.method_id))}</td><td class="numeric">${fmt(r.accuracy?.primary_error)}</td><td class="numeric">${fmt(r.simplicity?.weighted_operator_count)}</td><td class="numeric">${fmt(r.simplicity?.free_parameters)}</td><td>${tag(r.status)} ${b.pareto_front_rule_ids?.includes(r.rule_id)?'<span class="tag purple">Pareto</span>':r.accuracy_gate===false?'<span class="tag amber">Below gate</span>':''}</td></tr>`};
 return `<section class="panel"><div class="panel-head"><h3>${groups.length} distinct structures</h3><span class="hint">${b.rules.length} fitted submissions retained</span></div><p class="hint">Repeated structures are grouped, with every method and fitted value preserved. A shared form does not imply identical predictions or a verified mechanism.</p>${b.track?`<p class="note">${b.track==='primary'?'Frozen primary comparison':esc(b.track)+' · separate from the frozen primary comparison'}</p>`:''}<div class="table-wrap"><table class="leaderboard">${head}<tbody>${groups.map(g=>row(g[0],g.length>1?1:0)+(g.length>1?`<tr class="family-variants"><td colspan="6"><details><summary>Compare all ${g.length} fits · ${new Set(g.map(r=>r.method_id)).size} methods</summary><p class="hint">Each row has its own immutable submission and assessment. No scores are averaged or removed.</p><div class="table-wrap"><table>${head}<tbody>${g.map((r,i)=>row(r,i+1)).join('')}</tbody></table></div></details></td></tr>`:'')).join('')}</tbody></table></div></section><details class="panel"><summary>Attempt coverage · ${b.attempts?.length||0} retained outcomes</summary><div class="table-wrap"><table><thead><tr><th>Method</th><th>Status</th><th>Explanation</th></tr></thead><tbody>${(b.attempts||[]).map(a=>`<tr><td>${esc(methodName(a.method_id))}</td><td>${tag(a.status)}</td><td>${esc(a.reason||'Submission recorded')}</td></tr>`).join('')}</tbody></table></div></details><details class="panel"><summary>Assessment scope</summary><p>Loss is comparable within this task only. Simple controls remain useful competitors; added equations do not automatically improve a rule. Failed and invalid outcomes remain visible. Historical complexity labels are provisional; inherited fitted state is not fully counted. Scientific review is separate.</p>${reviewNotices(s.review_advisories)}</details>`}
function equationDetails(p){if(!p.equations?.length)return '';return `<details open class="rule-section equation-explainer"><summary>${p.equations.length} connected equations · quantities and assumptions</summary><div class="equation-flow">${p.equations.map((q,i)=>`<article class="quantity-card"><span class="eyebrow">Step ${i+1} · ${esc(q.unit)}</span><strong>${math(q.symbol)}</strong><p>${esc(q.meaning)}</p><small>Uses ${esc(q.dependencies.join(', '))}</small></article>`).join('')}</div><h3>Assumptions and boundaries</h3><ul>${p.assumptions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${p.identifiability?`<p class="note">Local fit identifiability: Jacobian rank ${p.identifiability.rank} of ${p.identifiability.parameters}. ${p.identifiability.rank_deficient?'Some parameters are locally unresolved.':'Full local rank does not establish a unique physical explanation.'}</p>`:''}</details>`}

function scenarioPage(id){const s=state.scenarios.find(s=>s.scenario_id===id);if(!s){$('#view').innerHTML='<p>Scenario not found.</p>';return}state.selected=id;chooseTask(s);$('#view').innerHTML=`<a class="text-link" href="#scenarios">← Scenario library</a>`+heading(s.domain,s.title,s.description)+`<div class="tabs scenario-tabs"><button id="explored-tab" class="active" aria-pressed="true">View explored rules</button><button id="about-tab" aria-pressed="false">About this scenario</button><button id="try-scenario" class="primary">Try it yourself</button></div><div id="scenario-content"></div>`;
 const selectedTab=explored=>{for(const [sel,on] of [['#explored-tab',explored],['#about-tab',!explored]]){$(sel).classList.toggle('active',on);$(sel).setAttribute('aria-pressed',String(on));}};
 const explored=()=>{selectedTab(true);$('#scenario-content').innerHTML=`<div class="toolbar"><div><label for="explored-task">Task</label><select id="explored-task">${s.tasks.map(t=>`<option value="${esc(t.task_id)}" ${t.task_id===state.task?'selected':''}>${esc(t.display_title)}</option>`).join('')}</select></div><button id="explored-download">Download results</button></div><div id="explored-board"></div>`;const render=async()=>{state.task=$('#explored-task').value;const t=taskFor(s),b=await loadBoard(id,t.task_id);if(!$('#explored-task')||$('#explored-task').value!==t.task_id)return;$('#explored-board').innerHTML=`<section class="panel">${taskPanel(t)}<p class="hint">${b?.rules.length||0} rules · ${b?.attempts?.length||0} retained attempts · ${esc(t.task_id)}</p></section>`+tableForTask(s,t,b);$('#explored-download').disabled=!b;$('#explored-download').onclick=()=>download(b,t.task_id+'-rules.json');document.querySelectorAll('[data-explored-rule]').forEach(el=>el.onclick=()=>{const r=b.rules.find(r=>r.rule_id===el.dataset.exploredRule);showRule(r.card||r,r,s.review_advisories,b.rule_presentations?.[r.rule_id])});bindVariables()};$('#explored-task').onchange=render;render()};
 const about=()=>{selectedTab(false);$('#scenario-content').innerHTML=`<div class="grid scenario-guide"><section class="panel">${scenarioDetails(s)}<h3>Tasks</h3>${s.tasks.map(t=>`<div class="guide-task">${taskPanel(t)}</div>`).join('')}<button id="new-guide-task">Add your own task</button></section><section class="panel"><h2>Scope and provenance</h2><p class="description">${esc(s.source_title)}</p><ul>${s.limitations.map(l=>`<li>${esc(l)}</li>`).join('')}</ul><p>${esc(s.source.license||'Source rights review required')}</p>${/^https?:\/\//.test(s.source.url||'')?`<a href="${esc(s.source.url)}" target="_blank" rel="noopener noreferrer">Original source ↗</a>`:''}<p class="hint">${s.publication_authorized?'Publication authorized by the source manifest.':'Redistribution authorization remains under review.'}</p>${reviewNotices(s.review_advisories)}</section></div>`;$('#new-guide-task').onclick=()=>addTask(s);bindVariables();bindPaths()};
 $('#explored-tab').onclick=explored;$('#about-tab').onclick=about;$('#try-scenario').onclick=()=>tryScenario(id,state.task);explored();}
function publicDiscover(){$('#view').innerHTML=heading('Private discovery','Your data. Your workspace.','Explore the shared examples here, then run your own method on your computer.')+`<section class="panel companion-panel"><h2>Start the local companion</h2><p>Local folders are read by the companion on your machine. Only the selected development context is sent directly to SiliconFlow when you choose an LLM method. Your API key and results never go to this website.</p><button class="primary" id="open-companion">Open local workspace</button><p class="hint">The companion requires Python 3.11 or later on macOS or Linux. Generated-code scoring requires the supported macOS sandbox; unsupported execution is refused.</p></section>`;$('#open-companion').onclick=()=>companionDialog(state.selected,state.task)}
function companionDialog(sid=state.selected,tid=state.task){const link='http://127.0.0.1:8150/#discover'+(sid?'/'+encodeURIComponent(sid):'')+(tid?'/'+encodeURIComponent(tid):'');$('#info-detail').innerHTML=`<div class="eyebrow">Private discovery</div><h2 id="info-title">Try it on your computer</h2><p>Run the local companion, then open your private workspace. This website does not connect to your local server or receive folders, keys or results.</p><ol class="setup-steps"><li>${state.config.companion_download?`<a href="${esc(siteUrl(state.config.companion_download.url))}" download>Download the companion bundle</a> and open the extracted public-release folder.`:'Extract the public-release distribution and open its folder.'}</li><li>In a terminal, change into the extracted folder and run:<pre class="formula">python3 -m venv ~/.principia-asd-venv
~/.principia-asd-venv/bin/pip install .
~/.principia-asd-venv/bin/principia-asd companion --bundle-root .</pre></li><li>Open the workspace, select your task and method, and add your SiliconFlow key in <strong>API settings</strong>.</li></ol><a class="button-link primary" href="${esc(link)}" target="_blank" rel="noopener noreferrer">Open local workspace ↗</a><p class="hint">If the workspace does not open, start the companion first. Only the public scenario and task IDs are passed in this link. Your private results stay under ~/.local/share/principia-asd.</p>`;$('#info-dialog').showModal()}
function requiredModels(){const mid=$('#method')?.value||'principia_engine';if(mid.startsWith('direct_'))return [state.config.model_aliases[mid.split('_')[1]]];const multiple=['principia_engine','principia_engine_explicit','agent_laboratory','agent_laboratory_explicit','data_to_paper','data_to_paper_explicit','asta_autodiscovery','agentrxiv','equation_agent'].includes(mid);return [...new Set((multiple?Object.keys(state.config.model_roles):['coder']).map(k=>$('#model-'+k)?.value||state.config.model_roles[k]))]}
async function providerDialog(message=''){
 if(isPublic){companionDialog();return;}
 state.config=await api('/api/config');const cfg=state.config,preferred=requiredModels();
 $('#provider-content').innerHTML=`<div class="eyebrow">Local provider connection</div><h2 id="provider-title">SiliconFlow API settings</h2>${message?`<p class="note">${esc(message)}</p>`:''}<p class="description">Your key is stored in a private file on this computer. It is used only by the local provider gateway and is never sent to the public website or included in downloaded results.</p><p id="key-status" class="hint">${cfg.api_configured?'A key is configured on this computer. Its value is never shown.':'No API key is configured. Numerical reference methods still work without a key.'}</p><form id="key-form"><label for="siliconflow-key">${cfg.api_configured?'Replace API key':'Your SiliconFlow API key'}</label><input type="password" id="siliconflow-key" autocomplete="off" spellcheck="false" placeholder="Paste your SiliconFlow key" maxlength="512"><div class="actions"><button type="submit" id="save-key" class="primary">Save key locally</button>${cfg.api_configured?'<button type="button" id="remove-key">Disconnect key</button>':''}</div></form><h3>Your model library</h3><p class="hint">Add exact SiliconFlow model IDs, edit generation and pricing settings, or remove models. Saved runs keep their original profiles.</p><div id="model-library"></div><div class="actions"><button id="add-model">Add model</button><button id="catalog-models" ${!cfg.api_configured?'disabled':''}>Browse provider catalog</button></div><div id="model-editor" class="hidden"></div><div id="catalog-results"></div><h3>Check model access</h3><p class="hint">One small, billed request per selected model. The reservation uses your saved pricing and reasoning bounds, including uncertain usage. No automatic retries or substitutions.</p><fieldset class="probe-models"><legend>Select models to check</legend>${cfg.models.map(m=>`<label class="variable-choice"><input type="checkbox" value="${esc(m)}" ${preferred.includes(m)?'checked':''}><span>${esc(m)}<small>${esc(cfg.capabilities[m]?.state||'Not checked')}</small></span></label>`).join('')}</fieldset><button id="check-models" ${!cfg.api_configured?'disabled':''}>Check selected models</button><p id="probe-progress" class="hint" role="status"></p><p class="error hidden" id="provider-error" role="alert"></p><button id="provider-done" class="link">Done — return to workspace</button>`;
 const fail=e=>{$('#provider-error').textContent=e.message;$('#provider-error').classList.remove('hidden')};
 $('#key-form').onsubmit=async e=>{e.preventDefault();const input=$('#siliconflow-key'),key=input.value;input.value='';$('#save-key').disabled=true;try{await api('/api/provider/key',{api_key:key});await providerDialog('Key saved on this computer. Check the models you plan to use.')}catch(e){fail(e);$('#save-key').disabled=false}};
 if($('#remove-key'))$('#remove-key').onclick=async()=>{try{await api('/api/provider/key',{action:'remove'});await providerDialog('Disconnected. An externally configured credential file, if any, is left unchanged.')}catch(e){fail(e)}};
 const price=()=>{const checked=[...document.querySelectorAll('.probe-models input:checked')],n=checked.length,reserved=checked.reduce((sum,x)=>sum+(cfg.probe_reservations[x.value]||2),0);$('#check-models').textContent=`Check ${n} model${n===1?'':'s'} · reserve up to CNY ${fmt(reserved)}`;$('#check-models').disabled=!cfg.api_configured||n===0||n>4};document.querySelectorAll('.probe-models input').forEach(e=>e.onchange=price);price();
 renderModelLibrary(cfg,fail);
 const poll=async()=>{try{const data=await api('/api/provider');if(!$('#provider-dialog').open)return;const active=['queued','running'].includes(data.probe.state);$('#probe-progress').textContent=active?'Checking selected models… You can close this dialog; the local check continues.':Object.entries(data.capabilities).map(([m,c])=>m+': '+c.state).join(' · ')||data.probe.message||'No checks recorded.';$('#check-models').disabled=active||!data.credential_status.configured;$('#save-key').disabled=active;if($('#remove-key'))$('#remove-key').disabled=active;if(!active){state.config=await api('/api/config');clearInterval(state.providerPoll)} }catch(e){fail(e);clearInterval(state.providerPoll)}};
 $('#check-models').onclick=async()=>{try{$('#check-models').disabled=true;await api('/api/provider/probe',{models:[...document.querySelectorAll('.probe-models input:checked')].map(e=>e.value),confirm_cost:true});clearInterval(state.providerPoll);state.providerPoll=setInterval(poll,2000);await poll()}catch(e){fail(e);price()}};
 $('#provider-done').onclick=()=>$('#provider-dialog').close();if(!$('#provider-dialog').open)$('#provider-dialog').showModal();
 if(['running','queued'].includes(cfg.provider_probe.state)){clearInterval(state.providerPoll);state.providerPoll=setInterval(poll,2000);await poll()}
}
function renderModelLibrary(cfg,fail){
 $('#model-library').innerHTML=cfg.models.length?cfg.models.map(m=>{const p=cfg.model_profiles[m];return `<article class="model-row"><div><strong>${esc(p.label||m)}</strong><code>${esc(m)}</code><small>CNY ${fmt(p.input_rate)} input / ${fmt(p.output_rate)} output per million tokens</small></div><div class="actions"><button class="small" data-edit-model="${esc(m)}">Edit</button><button class="small" data-remove-model="${esc(m)}">Remove</button></div></article>`}).join(''):'<p class="hint">No model profiles. Add one to use an LLM method; numerical methods remain available.</p>';
 const editor=(id='',suggestion='')=>{const p=cfg.model_profiles[id]||{input_rate:0,output_rate:0,options:{enable_thinking:false},reasoning_bound:0},on=p.options.enable_thinking===true;$('#model-editor').classList.remove('hidden');$('#model-editor').innerHTML=`<form id="profile-form" class="profile-form"><h4>${id?'Edit model':'Add model'}</h4><label for="profile-id">Exact model identifier</label><input id="profile-id" required maxlength="200" value="${esc(id||suggestion)}" placeholder="organization/model-name"><label for="profile-label">Display name</label><input id="profile-label" maxlength="200" value="${esc(p.label||id||suggestion)}" placeholder="Optional friendly name"><div class="grid"><div><label for="profile-input">Input · CNY / million tokens</label><input id="profile-input" type="number" min="0" max="1000" step="any" required value="${p.input_rate}"></div><div><label for="profile-output">Output · CNY / million tokens</label><input id="profile-output" type="number" min="0" max="1000" step="any" required value="${p.output_rate}"></div></div><label for="profile-date">Pricing verified on</label><input id="profile-date" type="date" required value="${esc(p.price_source?.date||new Date().toISOString().slice(0,10))}"><p class="hint">Enter current conservative rates from <a href="https://www.siliconflow.cn/pricing" target="_blank" rel="noopener noreferrer">SiliconFlow pricing</a>. Catalog access does not verify prices.</p><label for="profile-thinking">Reasoning configuration</label><select id="profile-thinking"><option value="disabled" ${p.options.enable_thinking===false?'selected':''}>Disable thinking explicitly</option><option value="default" ${p.options.enable_thinking===undefined?'selected':''}>No thinking option · non-reasoning model</option><option value="bounded" ${on?'selected':''}>Enable with a token reservation</option></select><div id="reasoning-fields" class="${on?'':'hidden'}"><label for="profile-bound">Reasoning token reservation</label><input id="profile-bound" type="number" min="1" max="32768" step="1" value="${p.reasoning_bound||1024}"><label for="profile-effort">Reasoning effort</label><select id="profile-effort"><option value="">Omit</option>${['low','medium','high'].map(x=>`<option ${p.options.reasoning_effort===x?'selected':''}>${x}</option>`).join('')}</select><p class="note">Provider enforcement varies by model. This reservation is not proof of a hard token limit. A capability check must pass before use; a bound violation stops the run and remains accounted.</p></div><div class="actions"><button type="submit" class="primary">Save model</button><button type="button" id="cancel-profile">Cancel</button></div></form>`;
 $('#profile-thinking').onchange=()=>$('#reasoning-fields').classList.toggle('hidden',$('#profile-thinking').value!=='bounded');$('#cancel-profile').onclick=()=>{$('#model-editor').replaceChildren();$('#model-editor').classList.add('hidden')};
 $('#profile-form').onsubmit=async e=>{e.preventDefault();const model=$('#profile-id').value.trim(),mode=$('#profile-thinking').value,options=mode==='default'?{}:{enable_thinking:mode==='bounded'},bound=mode==='bounded'?Number($('#profile-bound').value):0;if(mode==='bounded'){options.thinking_budget=bound;if($('#profile-effort').value)options.reasoning_effort=$('#profile-effort').value}try{await api('/api/provider/models',{original_id:id||null,model_id:model,profile:{label:$('#profile-label').value.trim()||model,input_rate:Number($('#profile-input').value),output_rate:Number($('#profile-output').value),options,reasoning_bound:bound,price_source:{date:$('#profile-date').value}}});await providerDialog('Model saved. Check access before starting a new LLM run.')}catch(e){fail(e)}};
 $('#profile-id').focus();};
 $('#add-model').onclick=()=>editor();document.querySelectorAll('[data-edit-model]').forEach(b=>b.onclick=()=>editor(b.dataset.editModel));document.querySelectorAll('[data-remove-model]').forEach(b=>b.onclick=async()=>{if(b.dataset.confirmRemove!=='yes'){b.dataset.confirmRemove='yes';b.textContent='Confirm removal';return;}try{await api('/api/provider/models',{action:'remove',model_id:b.dataset.removeModel});await providerDialog('Model removed. Existing runs and receipts are unchanged.')}catch(e){fail(e)}});
 $('#catalog-models').onclick=async()=>{const b=$('#catalog-models');b.disabled=true;b.textContent='Loading catalog…';try{const result=await api('/api/provider/catalog',{});$('#catalog-results').innerHTML=`<label for="provider-catalog">Available identifiers · ${result.models.length}</label><select id="provider-catalog">${result.models.map(m=>`<option>${esc(m)}</option>`).join('')}</select><button id="use-catalog-model">Configure selected model</button><p class="hint">${esc(result.message)}</p>`;$('#use-catalog-model').onclick=()=>{const id=$('#provider-catalog').value;editor(cfg.model_profiles[id]?id:'',id)}}catch(e){fail(e)}finally{b.disabled=false;b.textContent='Browse provider catalog'}};
}
for(const id of ['task-dialog','provider-dialog']){const d=$('#'+id);d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d)d.close()})}
$('#provider-dialog').addEventListener('close',()=>{clearInterval(state.providerPoll);$('#provider-content').replaceChildren();if(!isPublic&&location.hash.startsWith('#discover'))discover()});

async function loadBoard(sid,tid){const b=state.boards.find(b=>b.scenario_id===sid&&b.task_id===tid);if(isPublic&&b?.data_url&&!b.loaded){const detail=await api(b.data_url);if(detail.scenario_id!==sid||detail.task_id!==tid)throw Error('Task result identity does not match its catalog entry');Object.assign(b,detail,{loaded:true})}return b}
